-- FDA Drug wholesale: eight combined questions split (new DS09-DS17).
update public.hub_chk_points set q='Are wholesale licences 20B and 21B valid?', why='Selling drugs with a lapsed licence is an offence.', law='Drugs Rules r.61–63', evidence='Licences', updated_at=now() where code='DS01';
update public.hub_chk_points set q='Is the competent person named on the licence working with us?', why='Sale without the competent person breaks the licence condition.', law='Drugs Rules r.64; G.S.R. 135(E) 2026', evidence='Endorsement letter', updated_at=now() where code='DS02';
update public.hub_chk_points set q='Do we buy only from licensed manufacturers and dealers?', why='The purchase bill is our only defence if a drug is found spurious.', law='Drugs Rules r.65(4), r.65(5)', evidence='Supplier licence file', updated_at=now() where code='DS03';
update public.hub_chk_points set q='Do we sell only to licensed dealers, hospitals or doctors?', why='Sale to an unlicensed party is punishable.', law='Drugs Rules r.65(5)', evidence='Sales checked against licences', updated_at=now() where code='DS04';
update public.hub_chk_points set q='Does every sale invoice show batch number, expiry and manufacturer name?', why='Incomplete invoices are noted as violations in inspections.', law='Drugs Rules r.65(4)', evidence='Sample invoices', updated_at=now() where code='DS05';
update public.hub_chk_points set q='Are storage temperatures recorded daily?', why='Wrong storage spoils the drug and the dealer is held liable.', law='Drugs Rules r.65; Schedule P', evidence='Temperature log', updated_at=now() where code='DS06';
update public.hub_chk_points set q='Are expired and damaged goods kept separately and marked ''Not for sale''?', why='Expired stock on the sale shelf is an offence even if not sold.', law='Drugs Rules r.65(17)', evidence='Photo of expired-goods area', updated_at=now() where code='DS07';
update public.hub_chk_points set q='Do the premises match the approved plan?', why='An unreported change can cancel the licence.', law='Drugs Rules r.65A', evidence='Approved plan', updated_at=now() where code='DS08';
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DS09','FDA – Drug wholesale','Are the wholesale licences displayed at the premises?','Inspectors expect the licences on display.','Drugs Rules r.61–63','drug_sale',array['fda']::text[],'M','Photo of displayed licences',9849,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DS10','FDA – Drug wholesale','Is the licence retention fee paid?','A lapsed licence for non-payment of the retention fee is an offence.','Drugs Rules r.61–63','drug_sale',array['fda']::text[],'H','Fee receipt',9850,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DS11','FDA – Drug wholesale','Is the competent person present during sales?','Sale without the competent person breaks the licence condition.','Drugs Rules r.64; G.S.R. 135(E) 2026','drug_sale',array['fda']::text[],'H','Attendance record',9851,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DS12','FDA – Drug wholesale','Do we keep every purchase bill for 3 years?','The purchase bill is our only defence if a drug is found spurious.','Drugs Rules r.65(4), r.65(5)','drug_sale',array['fda']::text[],'H','Purchase file',9852,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DS13','FDA – Drug wholesale','Do we keep a copy of each buyer''s licence?','Sale to an unlicensed party is punishable.','Drugs Rules r.65(5)','drug_sale',array['fda']::text[],'H','Customer licence file',9853,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DS14','FDA – Drug wholesale','Does every sale invoice show both parties'' licence numbers?','Incomplete invoices are noted as violations in inspections.','Drugs Rules r.65(4)','drug_sale',array['fda']::text[],'M','Sample invoices',9854,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DS15','FDA – Drug wholesale','Is there a working fridge, with a log, for 2–8°C products?','Wrong storage spoils the drug and the dealer is held liable.','Drugs Rules r.65; Schedule P','drug_sale',array['fda']::text[],'H','Fridge log',9855,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DS16','FDA – Drug wholesale','Are expired and damaged goods returned or destroyed, with a record?','Expired stock on the sale shelf is an offence even if not sold.','Drugs Rules r.65(17)','drug_sale',array['fda']::text[],'M','Expiry register',9856,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DS17','FDA – Drug wholesale','Was any change in premises or constitution informed to FDA?','An unreported change can cancel the licence.','Drugs Rules r.65A','drug_sale',array['fda']::text[],'M','Intimations to FDA',9857,true,null) on conflict (code) do nothing;
