-- Existing answers (Velite India): 'Yes' that covered both halves is copied to the new question; DS06 and DS07 'No' are flagged for re-check.
insert into public.hub_chk_answers(firm_id, code, answer, note, ref_no, proof_link, proof_path, proof_name, answered_by, answered_by_name, answered_at)
  select firm_id, t.c, answer, note, ref_no, proof_link, proof_path, proof_name, answered_by, answered_by_name, answered_at from public.hub_chk_answers, (values ('DS01','DS09'),('DS01','DS10'),('DS02','DS11'),('DS03','DS12'),('DS04','DS13'),('DS05','DS14'),('DS08','DS17')) as t(f,c) where code=t.f and firm_id='VI' and answer in ('yes','na') on conflict do nothing;
update public.hub_chk_answers set stale=true, stale_reason='question was split in two, please confirm this still applies' where code in ('DS06','DS07') and firm_id='VI';
